    SceneState moving=plain;moving.lanes.resize(1);auto &moving_actor=moving.lanes[0];moving_actor.frames.resize(1);auto &moving_frame=moving_actor.frames[0];moving_frame.x=3;moving_frame.y=8;moving_frame.visible_from=2;moving_frame.visible_until=10;moving_frame.vx=2;moving_frame.vy=-1;SceneProject endpoint(moving);CHECK(endpoint.reverse_actor(moving_actor.id,error)==0);auto &end=endpoint.state.lanes[0].frames[0];CHECK(end.x==19&&end.y==0&&end.visible_from==0&&end.visible_until==8&&end.vx==-2&&end.vy==1);CHECK(poses(moving,moving_actor.id,10)==""); // Hide is exclusive.
    // Stateless single-frame reverse is a no-op and must keep a Redo branch.
    auto single=plain;single.lanes.resize(1);single.lanes[0].frames.resize(1);SceneProject noop(single,false);noop.begin("Position");noop.state.lanes[0].x++;noop.commit();noop.undo();auto snapshot=state(noop.state);CHECK(noop.reverse_actor(single.lanes[0].id,error)==0&&state(noop.state)==snapshot&&!noop.can_undo()&&noop.can_redo()&&!noop.dirty());
    for(auto id:{0ull,999999ull}){snapshot=state(project.state);bool undo=project.can_undo(),redo=project.can_redo();CHECK(project.reverse_actor(id,error)==-1&&state(project.state)==snapshot&&project.can_undo()==undo&&project.can_redo()==redo);}project.begin("Pending");CHECK(project.reverse_actor(10,error)==-1&&project.transaction_open());project.cancel();
    auto reject=[&](SceneState s){SceneProject p(s);p.begin("Position");p.state.lanes[0].x++;p.commit();p.undo();auto was=state(p.state);CHECK(p.reverse_actor(10,error)==-1&&!error.empty()&&state(p.state)==was&&!p.can_undo()&&p.can_redo());};
    auto overflow=initial;overflow.lanes[1].frames[1].x=4095;overflow.lanes[1].frames[1].vx=128;overflow.lanes[1].frames[1].cap_x=0;reject(overflow);overflow=initial;overflow.lanes[1].frames[1].dual_x=-4095;overflow.lanes[1].frames[1].vx=-128;overflow.lanes[1].frames[1].cap_x=0;reject(overflow);overflow=initial;auto repeated=overflow.lanes[1].frames[1];repeated.id=0;repeated.ticks=255;repeated.vx=repeated.vy=0;overflow.lanes[1].frames.assign(400,repeated);reject(overflow);
    auto invalid=initial;invalid.lanes[1].trigger_lane=10;invalid.lanes[1].trigger_frame=11;reject(invalid);
    auto long_run=plain;long_run.lanes.resize(2);long_run.lanes[1].frames.assign(400,plain.lanes[1].frames[0]);for(auto &f:long_run.lanes[1].frames){f.id=0;f.ticks=255;}long_run.lanes[1].frames[0].visible_from=1;long_run.lanes[1].frames[0].visible_until=2;SceneProject long_project(long_run);snapshot=state(long_project.state);CHECK(long_project.reverse_actor(10,error)==-1&&error.find("timing limits")!=std::string::npos&&state(long_project.state)==snapshot&&!long_project.can_undo());
    // Fail at every preparation/history allocation position. No partial
