    int failed=0,succeeded=0;for(int n=0;n<1500;++n){SceneProject p(initial);p.begin("Position");p.state.lanes[0].x++;p.commit();p.undo();snapshot=state(p.state);int result=-1;fail_after=n;try{result=p.reverse_actor(10,error);}catch(const std::bad_alloc &){}fail_after=-1;if(result<0){++failed;CHECK(state(p.state)==snapshot&&!p.can_undo()&&p.can_redo()&&p.allocate_id()==22);}else{++succeeded;CHECK(result==1&&!p.can_redo());p.undo();CHECK(state(p.state)==snapshot);}}CHECK(failed>20&&succeeded>0);
    CHECK(a->generation()==ga&&b->generation()==gb&&!a->dirty()&&!b->dirty()&&read(root/"a.IMG")==a_bytes&&read(root/"b.IMG")==b_bytes&&g_doc==nullptr);CHECK(fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent));if(!failures&&fs::weakly_canonical(root).parent_path()==fs::weakly_canonical(parent))fs::remove_all(root);if(failures)std::cerr<<"Artifacts: "<<root<<'\n';std::cout<<"Actor reverse: "<<failures<<" failure(s)\n";return failures?1:0;
